/* Includes ------------------------------------------------------------------*/
#include "ax_kinematics.h"
#include "ax_robot.h"
#include "ax_speed.h"


//根据机器人类型，选择编译机器人运动学处理函数


void ROBOT_AKM_Kinematics(void);

/**
  * @简  述  机器人运动学处理，不同类型底盘进入不同处理函数
  * @参  数  无
  * @返回值  无
  */
void AX_ROBOT_Kinematics(void)
{	
	
	//判断机器人运动是否开启
	if(ax_robot_move_enable == 0)
	{
		//目标速度设置为0
		R_Vel.TG_IX = 0;
		R_Vel.TG_IY = 0;
		R_Vel.TG_IW = 0;
	}
	
	ROBOT_AKM_Kinematics();
}


/**
  * @简  述  机器人运动学处理-阿克曼
  * @参  数  无
  * @返回值  无
  */
/* @L62 函数契约 ------------------------------------------------
 * 输入（全部是全局变量，没有形参，这是厂商代码的风格）：
 *   R_Vel.TG_IX  0.001 m/s    上位机目标前进速度
 *   R_Vel.TG_IW  0.001 rad/s  上位机目标横摆角速度（本函数其实不用它！见下）
 *   ax_akm_angle 0.001 rad    已由 ax_uart4.c + ax_akm.c 换算好的前轮角
 * 输出：
 *   R_Wheel_A/B.TG/PWM、舵机角度、R_Vel.RT_IX/RT_IW（回传给上位机）
 * 注意：本函数不读 TG_IW，转向只由 ax_akm_angle 决定 —— 也就是说
 *       "速度->转角"的换算发生在上位机帧到达的那一刻（ax_uart4.c:175），
 *       而不是在 50Hz 控制循环里。这个时序差别在排查"转向滞后"时要记得。
 * ------------------------------------------------------------- */
void ROBOT_AKM_Kinematics(void)
{

	float akm_spd;  //速度
    float akm_angle; //前轮转向角度
	float akm_angle_r;  //右前轮转向角度
	float akm_angle_s;  //舵机转向角度
	float radius;  //转弯半径
	int16_t servo_angle; //舵机控制角度
	
	//通过编码器获取车轮实时转速m/s
/* @L73 编码器"读后清零" -----------------------------------------
 * 这里取的是"过去 20ms 内的脉冲数"，不是累计值：
 *   读计数 -> 立即清零 -> 下一周期再读到的就是新的增量。
 * AKM_WHEEL_SCALE 的量纲推导（ax_robot.h:156）：
 *   πD × PID_RATE / 1560 = π×0.065×50/1560 ≈ 0.006545
 *   脉冲数 × 该系数 = (脉冲/20ms) 折算成 m/s。
 * 为什么 B 轮前面有负号：左右电机镜像安装，同一前进方向下编码器计数方向相反。
 * 这个"符号差"在仿真里对应你踩过的轮序 bug，实体上就是这两行。
 * 风险：计数被强制转 int16_t，若 20ms 内脉冲超过 ±32767 会溢出（不可能，
 * 满速约 230 脉冲）；但若本函数被意外以更高频率调用，清零会导致速度被低估。
 * ------------------------------------------------------------- */
	R_Wheel_A.RT = (float) ((int16_t)AX_ENCODER_A_GetCounter()*AKM_WHEEL_SCALE);
	AX_ENCODER_A_SetCounter(0);
	R_Wheel_B.RT = (float)-((int16_t)AX_ENCODER_B_GetCounter()*AKM_WHEEL_SCALE);
	AX_ENCODER_B_SetCounter(0);	
	
	//调试输出轮子转速
	//printf("@%f  %f   \r\n",R_Wheel_A.RT,R_Wheel_B.RT);
	
	/*******正向运动学解析(根据前进速度和舵机转角计算)*********************************/
	
/* @L84 限幅：只限了速度，没限转角（P2）-------------------------
 * 84~85：vx 限到 ±1500 (0.001 m/s) 即 ±1.5 m/s。
 * 88~89：转向角限幅被整段注释掉了 ——> 上位机若发出 ax_akm_angle=3000
 *        (3 rad = 172°)，这里会直接 tan(3.0) 得到 -0.1425，
 *        半径变成负数，左右轮目标速度互换（车会反打）。
 * 上游兜底：ax_akm.c:48 用最小转弯半径 0.35m 把角度钳在 atan(0.146/0.35)=22.6°，
 *       所以从 0x50 帧进来的角度是安全的。但 0x60/APP/PS2 等其它路径
 *       也会写 ax_akm_angle，这里就没有保护了。
 * ------------------------------------------------------------- */
	//机器人目标速度限制
	if( R_Vel.TG_IX > R_VX_LIMIT )    R_Vel.TG_IX = R_VX_LIMIT;
	if( R_Vel.TG_IX < (-R_VX_LIMIT))  R_Vel.TG_IX = (-R_VX_LIMIT);
	
	//转向角度限制
//	if( ax_akm_angle > R_VX_LIMIT )    ax_akm_angle = R_VX_LIMIT;
//	if( ax_akm_angle < (-R_VX_LIMIT))  ax_akm_angle = (-R_VX_LIMIT);
	
	//转换为浮点数计算
/* @L92 定点 -> 浮点：0.001 单位还原成 SI -----------------------
 * TG_IX(0.001 m/s) / 1000 = m/s；ax_akm_angle(0.001 rad) / 1000 = rad。
 * 全固件所有 int16 速度量的 1000 倍缩放都发生在"打包/解包"边界，
 * 内部计算一律 SI —— 这条纪律你们上位机 protocol.py 也是照抄的。
 * ------------------------------------------------------------- */
	akm_spd = R_Vel.TG_IX/1000.0;
	akm_angle = ax_akm_angle/1000.0;
	
	//根据转向角度计算转弯半径
/* @L96 阿克曼核心公式（此处 akm_angle 是弧度，正确）-------------
 *   R = L / tan(δ)
 * L = AKM_ACLE_BASE = 0.146 m（轴距），δ = 虚拟前轮（车身中心线）转角。
 * 与仿真侧 steering_odometry.cpp 的 IK 是同一族公式。
 * 边界：δ=0 时 tan=0，R=∞ —— 能算出 inf，后续 R∓w/2 会得到 inf/inf=nan。
 *       但 99 行用 if(ax_akm_angle != 0) 分流避开了，这也是这个 if 存在的真正原因。
 * ------------------------------------------------------------- */
	radius = AKM_ACLE_BASE/tan(akm_angle);		
	
	//根据前轮角度计算右前轮角度
	if(ax_akm_angle !=0 )
	{

		//运动学逆解析，由机器人目标速度计算电机轮子速度（m/s）
/* @L103 差速分配：同一角速度下内外轮线速度不同 -------------------
 *   v_内 = v·(R - w/2)/R      v_外 = v·(R + w/2)/R ，w=0.160 m 轮距
 * A=左后、B=右后（按编码器 A/B 命名，实际左右以接线为准）。
 * 注意这里直接乘除 radius，没有用 tan，所以 R 为负（倒车打方向）时公式依然成立。
 * 对照：仿真侧 steering_odometry.cpp 的 FK 往返 bug 就出在"内外轮判断"
 * 和"用哪个公式求逆"上，这里靠"同一公式正反用"天然互逆。
 * ------------------------------------------------------------- */
		R_Wheel_A.TG = akm_spd*(radius-0.5*AKM_WHEEL_BASE)/radius;
		R_Wheel_B.TG = akm_spd*(radius+0.5*AKM_WHEEL_BASE)/radius;					
		
		//计算右前轮角度
/* @L107 ★★ 全文件最需要警惕的一行：弧度被当成度数（P1）★★ --------
 * 137~139 行的 FK 说明 R_Vel.TG_IX 是 0.001 m/s；同理 ax_akm_angle 是 0.001 rad，
 * 93 行还原成弧度 akm_angle。那么这一行正确的写法应该是：
 *     akm_angle_r = atan(L / (L/tan(akm_angle) + w/2));      // 结果弧度
 * 实际却写成 tan(akm_angle*0.01745) —— 0.01745≈π/180，等于认为 akm_angle 是"度"。
 * 但行尾又 *(180.0/PI) 把结果转成"度"，而 120 行紧接着再 ×180/π。
 *
 * 数值验算（δ=0.235 rad = 13.5°）：
 *   正确：R=0.6106，δ_r=atan(0.146/(0.6106+0.08))=0.2084 rad=11.94°
 *   实际：tan(0.235×0.01745)=tan(0.0041)=0.0041 -> R'=35.6
 *         -> δ_r'=atan(0.146/(35.6+0.08))=0.00409 rad，×(180/π)=0.2345°
 * 因为 tan(x·0.01745)≈x·0.01745 且 ×57.3 又把它放大回去，两次换算近似抵消：
 *   δ_r' ≈ δ 的数值，但单位被当成"度" -> 120 行再 ×57.3 -> 舵机 -16.2°
 * 而正确值应为 -14.4°。净效果：约 +12% 舵机增益，梯形连杆的二次补偿项
 * （0.0041·δ²）几乎被清零，轮距修正也丢了。车能开，但转向偏大且不线性。
 *
 * 结论：这不是"舵机不转"级别的 bug。修法见 README_ANNOTATED.md 的 P1。
 * 旁证：更老的 robot.c:214 有完全相同的写法 -> 这是一条复制粘贴遗传下来的缺陷。
 * ------------------------------------------------------------- */
		akm_angle_r = (atan(AKM_ACLE_BASE/((AKM_ACLE_BASE/tan(akm_angle))+0.5*AKM_WHEEL_BASE)));
	}
	else
	{
		//运动学逆解析，由机器人目标速度计算电机轮子速度（m/s）
		R_Wheel_A.TG = akm_spd;
		R_Wheel_B.TG = akm_spd;	
		
		//计算右前轮角度
		akm_angle_r = 0;
	}	
	
    //根据右前轮角度，计算舵机转向角度
/* @L120 舵机映射：梯形连杆非线性用二次多项式拟合 -----------------
 *   servo_deg = -(0.0041·δ_r² + 1.2053·δ_r) ，再 ×180/π
 * 物理含义：舵机输出的是"摆臂角"，前轮是"车轮角"，梯形转向连杆让两者
 *   不成正比（中间快、两端慢）。0.0041 是二次项系数，1.2053 是一次项系数，
 *   负号表示舵机安装方向与车轮转角相反。
 * 工程注意：
 *   1) 这两个系数是"这一台车、这一个舵机、这一套连杆"的标定值，
 *      换舵机/换连杆/拆装后必须重新标定，无法从图纸推出；
 *   2) 这里的 ×180/π 意味着 107 行本应输出弧度（见 P1）；
 *   3) 一次项 1.2053 说明"舵机角 ≈ 1.2×车轮角"，杠杆比大于 1。
 * 标定方法（S8 用）：给若干 δ，用量角器量实际前轮角，最小二乘拟合二次曲线。
 * ------------------------------------------------------------- */
	akm_angle_s = 	-(0.0041*akm_angle_r*akm_angle_r + 1.2053*akm_angle_r)*180/PI;
	
	//根据舵机转向角度，计算舵机PWM控制量
/* @L123 舵机指令 = 0.1 度单位 + 零偏 -----------------------------
 * AX_SERVO_S3_SetAngle 接收 0.1° 整数（1500us 舵机常见约定，±900 = ±90°）。
 * AKM_ANGLE_OFFSET（ax_robot.h:215）是"机械零位修正"：
 *   装配误差导致舵机中位与车轮直行不一致时改这个常量，不要改公式。
 * 所以伺服链路:  δ(rad) -> δ_r(deg, 有 bug) -> servo_deg -> ×10 -> PWM。
 * ------------------------------------------------------------- */
	servo_angle = (akm_angle_s*10 + AKM_ANGLE_OFFSET);  
	
	//设置舵机角度
	AX_SERVO_S3_SetAngle(servo_angle);	
	
	//利用PID算法计算电机PWM值
/* @L129 轮速闭环：每轮独立 PID ---------------------------------
 * AX_SPEED_PidCtlA/B 定义在 ax_speed.c，是"增量式"写法：
 *   pwm += Kp·e + Kd·(e - e_last)
 * 注意这个形式里累加项相当于积分（Kp=700），差分项相当于比例（Kd=900），
 * 与教科书式 PID 的 Kp/Kd 含义不同，调参时不要按经典 PID 的直觉来。
 * 输出限幅 ±4200（见 ax_speed.c:51）。
 * 电机设置处（133~134）没有取负，而更老的 robot.c 里是取负的（-PWM），
 * 说明 B20 的电机接线方向与 RP 版相反 —— 移植代码时这类符号千万不要照抄。
 * ------------------------------------------------------------- */
	R_Wheel_A.PWM = AX_SPEED_PidCtlA(R_Wheel_A.TG, R_Wheel_A.RT);   
	R_Wheel_B.PWM = AX_SPEED_PidCtlB(R_Wheel_B.TG, R_Wheel_B.RT);   
		
	//设置电机PWM值
	AX_MOTOR_A_SetSpeed(R_Wheel_A.PWM);
	AX_MOTOR_B_SetSpeed(R_Wheel_B.PWM); 	
	
	//运动学正解析，由机器人轮子速度计算机器人速度
/* @L137 正运动学回传：注意它怎么算 yaw rate（P3）----------------
 *   vx = (v_L + v_R)/2
 *   wz = (v_R - v_L)/w        <- 用左右轮速差估计横摆角速度
 * 这个 wz 在纯滚动假设下是准的，但实车转弯时轮胎侧滑会让内侧轮相对地面
 * 多走、外侧轮少走，导致 wz 被系统性高估（你们的圆周实验实测约 6%）。
 * 这是物理误差，不是代码 bug —— 也是 S3 融合必须引入陀螺仪的根本原因：
 * 短时用陀螺（准、但漂），长时用轮速（不漂、但有侧滑偏置）。
 * 另外注意：这里没有用到 ax_akm_angle，说明上位机拿到的 wz 完全来自轮速，
 * 与它自己下发的 vw 无关，所以"下发的 vw"和"回传的 wz"对不上是正常的。
 * ------------------------------------------------------------- */
	R_Vel.RT_IX = ((R_Wheel_A.RT + R_Wheel_B.RT)/2)*1000;
	R_Vel.RT_IY = 0;
	R_Vel.RT_IW = ((-R_Wheel_A.RT + R_Wheel_B.RT)/AKM_WHEEL_BASE)*1000;	
}

